const startItem = $('Start').first().json || {};
const triggerData = startItem.body || startItem.payload || startItem || {};
const configs = startItem.configs || triggerData.configs || {};
const loja = $input.item.json || {};
const evoConfig = loja.config_json?.evolutionapi || {};

const defaultEvolutionKey = (configs.evolution_api_key || '').trim();
const defaultEvolutionUrl = (configs.evolution_api_url || '').replace(/\/+$/, '');

let instanceName = (evoConfig.instanceName || '').trim();
if (!instanceName || instanceName === 'loja-undefined' || instanceName === 'loja-null') {
  instanceName = `loja-${loja.id}`;
}

const apikey = (evoConfig.apikey || '').trim() || defaultEvolutionKey;
let apiUrl = (evoConfig.apiUrl || '').trim().replace(/\/+$/, '');
if (!apiUrl) {
  apiUrl = defaultEvolutionUrl;
}

const evolutionAction = (triggerData.evolutionAction || 'STATUS').toUpperCase();
const isReset = evolutionAction === 'RESET';

if (!apiUrl || !instanceName || !apikey) {
  return {
    json: {
      hasError: true,
      error: 'Instância, chave ou URL da Evolution API não configurada na loja ou na tabela configs.'
    }
  };
}

let webhookUrl = (evoConfig.webhookUrl || configs.evolution_webhook_url || loja.config_evo_webhook || '').trim();
if (webhookUrl && !webhookUrl.includes('/app/')) {
  webhookUrl = webhookUrl.replace('/adswhatsinbound', '/app/adswhatsinbound');
}

const rawToken = (evoConfig.token || '').trim();
const instanceToken = rawToken || ('TOKEN-' + loja.id);
const webhookSecret = (configs.webhook_secret || loja.config_evo_secret || instanceToken || apikey || '').trim();

const createPayload = {
  instanceName,
  qrcode: true,
  integration: 'WHATSAPP-BAILEYS',
  token: instanceToken,
  webhook: {
    enabled: Boolean(webhookUrl),
    url: webhookUrl,
    headers: {
      'x-webhook-secret': webhookSecret
    },
    byEvents: false,
    base64: false,
    events: [
      'MESSAGES_UPSERT',
      'CONNECTION_UPDATE'
    ]
  }
};

let url = '';
let method = 'GET';

if (evolutionAction === 'STATUS') {
  url = `${apiUrl}/instance/fetchInstances?instanceName=${instanceName}`;
} else if (evolutionAction === 'CONNECT') {
  url = `${apiUrl}/instance/connect/${instanceName}`;
} else if (evolutionAction === 'LOGOUT') {
  url = `${apiUrl}/instance/logout/${instanceName}`;
  method = 'DELETE';
} else if (evolutionAction === 'RESTART') {
  url = `${apiUrl}/instance/restart/${instanceName}`;
  method = 'POST';
} else {
  url = `${apiUrl}/instance/fetchInstances?instanceName=${instanceName}`;
}

return {
  json: {
    hasError: false,
    evolutionAction,
    isReset,
    url,
    method,
    apikey,
    instanceName,
    loja_id: loja.id,
    logoutUrl: `${apiUrl}/instance/logout/${instanceName}`,
    deleteUrl: `${apiUrl}/instance/delete/${instanceName}`,
    createUrl: `${apiUrl}/instance/create`,
    connectUrl: `${apiUrl}/instance/connect/${instanceName}`,
    createPayload
  }
};

const res = $input.item.json;
const item = Array.isArray(res) ? (res[0] || {}) : res;
const loja = $('Buscar Loja').first().json || {};

const rawOwner = item?.ownerJid || item?.owner || item?.number || item?.instance?.ownerJid || item?.instance?.owner || item?.instance?.number || item?.profile?.id || '';
const cleanPhone = rawOwner ? String(rawOwner).split('@')[0].split(':')[0].replace(/\D/g, '') : '';
const formattedPhone = cleanPhone ? (cleanPhone.startsWith('55') ? cleanPhone : ('55' + cleanPhone)) : '';

const rawState = item?.connectionStatus || item?.instance?.state || item?.instance?.status || item?.status || item?.state || '';
const base64 = item?.base64 || item?.qrcode?.base64 || null;
const code = item?.code || item?.qrcode?.code || null;
const profilePicUrl = item?.profilePicUrl || item?.instance?.profilePicUrl || null;

// Sanitiza o retorno para expor apenas dados seguros de estado e QR Code, nunca tokens ou apikeys
const safeData = {
  connectionStatus: rawState,
  state: rawState,
  base64,
  code,
  number: formattedPhone || null,
  profilePicUrl
};

// Só tenta atualizar o banco se a loja não tiver telefone cadastrado ainda
const currentPhone = loja.whatsapp_loja || '';
const shouldUpdate = Boolean(formattedPhone && loja.id && !currentPhone);

return {
  json: {
    ok: true,
    data: safeData,
    ownerPhone: formattedPhone,
    number: formattedPhone,
    loja_id: loja.id,
    shouldUpdate
  }
};

const original = $('Formatar Resposta').first().json;
return {
  json: {
    ok: true,
    data: original.data,
    ownerPhone: original.ownerPhone,
    number: original.ownerPhone
  }
};
